import React, { useState } from 'react';

const CourseContentBuilder = ({ modules, onChange }) => {
  const [expandedModule, setExpandedModule] = useState(null);

  const addModule = () => {
    const newModule = {
      id: Date.now().toString(),
      title: '',
      description: '',
      lessons: []
    };
    onChange([...modules, newModule]);
  };

  const updateModule = (moduleId, field, value) => {
    const updatedModules = modules.map(module =>
      module.id === moduleId ? { ...module, [field]: value } : module
    );
    onChange(updatedModules);
  };

  const deleteModule = (moduleId) => {
    const updatedModules = modules.filter(module => module.id !== moduleId);
    onChange(updatedModules);
  };

  const addLesson = (moduleId) => {
    const newLesson = {
      id: Date.now().toString(),
      title: '',
      type: 'video', // video, text, document, quiz
      content: '',
      duration: 0,
      resources: []
    };

    const updatedModules = modules.map(module =>
      module.id === moduleId
        ? { ...module, lessons: [...module.lessons, newLesson] }
        : module
    );
    onChange(updatedModules);
  };

  const updateLesson = (moduleId, lessonId, field, value) => {
    const updatedModules = modules.map(module =>
      module.id === moduleId
        ? {
            ...module,
            lessons: module.lessons.map(lesson =>
              lesson.id === lessonId ? { ...lesson, [field]: value } : lesson
            )
          }
        : module
    );
    onChange(updatedModules);
  };

  const deleteLesson = (moduleId, lessonId) => {
    const updatedModules = modules.map(module =>
      module.id === moduleId
        ? {
            ...module,
            lessons: module.lessons.filter(lesson => lesson.id !== lessonId)
          }
        : module
    );
    onChange(updatedModules);
  };

  const handleFileUpload = (moduleId, lessonId, file) => {
    // In a real implementation, this would upload to a cloud storage service
    // For now, we'll just store the file info
    const fileInfo = {
      name: file.name,
      type: file.type,
      size: file.size,
      url: URL.createObjectURL(file) // This is just for preview - not for production
    };

    updateLesson(moduleId, lessonId, 'content', fileInfo.url);

    // Add to resources
    const updatedModules = modules.map(module =>
      module.id === moduleId
        ? {
            ...module,
            lessons: module.lessons.map(lesson =>
              lesson.id === lessonId
                ? { ...lesson, resources: [...lesson.resources, fileInfo] }
                : lesson
            )
          }
        : module
    );
    onChange(updatedModules);
  };

  return (
    <div className="course-content-builder">
      <div className="content-builder-header">
        <h2>Course Content</h2>
        <p>Build your course with modules and lessons</p>
      </div>

      <div className="modules-list">
        {modules.map((module, moduleIndex) => (
          <div key={module.id} className="module-item">
            <div className="module-header">
              <div className="module-info">
                <input
                  type="text"
                  placeholder="Module Title"
                  value={module.title}
                  onChange={(e) => updateModule(module.id, 'title', e.target.value)}
                  className="module-title-input"
                />
                <textarea
                  placeholder="Module Description"
                  value={module.description}
                  onChange={(e) => updateModule(module.id, 'description', e.target.value)}
                  className="module-description-input"
                  rows="2"
                />
              </div>
              <div className="module-actions">
                <button
                  type="button"
                  onClick={() => setExpandedModule(
                    expandedModule === module.id ? null : module.id
                  )}
                  className="btn btn-secondary btn-sm"
                >
                  {expandedModule === module.id ? 'Collapse' : 'Expand'}
                </button>
                <button
                  type="button"
                  onClick={() => deleteModule(module.id)}
                  className="btn btn-danger btn-sm"
                >
                  Delete Module
                </button>
              </div>
            </div>

            {expandedModule === module.id && (
              <div className="module-content">
                <div className="lessons-section">
                  <div className="lessons-header">
                    <h4>Lessons</h4>
                    <button
                      type="button"
                      onClick={() => addLesson(module.id)}
                      className="btn btn-primary btn-sm"
                    >
                      Add Lesson
                    </button>
                  </div>

                  <div className="lessons-list">
                    {module.lessons.map((lesson, lessonIndex) => (
                      <div key={lesson.id} className="lesson-item">
                        <div className="lesson-header">
                          <input
                            type="text"
                            placeholder="Lesson Title"
                            value={lesson.title}
                            onChange={(e) => updateLesson(module.id, lesson.id, 'title', e.target.value)}
                            className="lesson-title-input"
                          />
                          <div className="lesson-controls">
                            <select
                              value={lesson.type}
                              onChange={(e) => updateLesson(module.id, lesson.id, 'type', e.target.value)}
                              className="lesson-type-select"
                            >
                              <option value="video">Video</option>
                              <option value="text">Text/Article</option>
                              <option value="document">Document</option>
                              <option value="quiz">Quiz</option>
                            </select>
                            <input
                              type="number"
                              placeholder="Duration (min)"
                              value={lesson.duration}
                              onChange={(e) => updateLesson(module.id, lesson.id, 'duration', parseInt(e.target.value) || 0)}
                              className="lesson-duration-input"
                              min="0"
                            />
                            <button
                              type="button"
                              onClick={() => deleteLesson(module.id, lesson.id)}
                              className="btn btn-danger btn-sm"
                            >
                              ×
                            </button>
                          </div>
                        </div>

                        <div className="lesson-content">
                          {lesson.type === 'video' && (
                            <div className="video-upload">
                              <input
                                type="file"
                                accept="video/*"
                                onChange={(e) => {
                                  if (e.target.files[0]) {
                                    handleFileUpload(module.id, lesson.id, e.target.files[0]);
                                  }
                                }}
                                className="file-input"
                              />
                              <p className="upload-help">Upload video file or paste video URL</p>
                              <input
                                type="url"
                                placeholder="Or paste video URL (YouTube, Vimeo, etc.)"
                                value={lesson.content}
                                onChange={(e) => updateLesson(module.id, lesson.id, 'content', e.target.value)}
                                className="video-url-input"
                              />
                            </div>
                          )}

                          {lesson.type === 'text' && (
                            <div className="text-content">
                              <textarea
                                placeholder="Write your lesson content here..."
                                value={lesson.content}
                                onChange={(e) => updateLesson(module.id, lesson.id, 'content', e.target.value)}
                                className="lesson-text-content"
                                rows="6"
                              />
                              <p className="content-help">You can use Markdown formatting</p>
                            </div>
                          )}

                          {lesson.type === 'document' && (
                            <div className="document-upload">
                              <input
                                type="file"
                                accept=".pdf,.doc,.docx,.ppt,.pptx,.txt"
                                onChange={(e) => {
                                  if (e.target.files[0]) {
                                    handleFileUpload(module.id, lesson.id, e.target.files[0]);
                                  }
                                }}
                                className="file-input"
                              />
                              <p className="upload-help">Upload PDF, Word, PowerPoint, or text files</p>
                              {lesson.resources.length > 0 && (
                                <div className="uploaded-files">
                                  <h5>Uploaded Files:</h5>
                                  {lesson.resources.map((resource, index) => (
                                    <div key={index} className="file-item">
                                      <span>{resource.name}</span>
                                      <span className="file-size">({(resource.size / 1024 / 1024).toFixed(2)} MB)</span>
                                    </div>
                                  ))}
                                </div>
                              )}
                            </div>
                          )}

                          {lesson.type === 'quiz' && (
                            <div className="quiz-builder">
                              <textarea
                                placeholder="Quiz instructions and questions (for now, this is a text field - full quiz builder coming soon)"
                                value={lesson.content}
                                onChange={(e) => updateLesson(module.id, lesson.id, 'content', e.target.value)}
                                className="quiz-content"
                                rows="4"
                              />
                              <p className="content-help">Advanced quiz builder coming soon!</p>
                            </div>
                          )}
                        </div>
                      </div>
                    ))}

                    {module.lessons.length === 0 && (
                      <div className="no-lessons">
                        <p>No lessons yet. Click "Add Lesson" to get started.</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}

        {modules.length === 0 && (
          <div className="no-modules">
            <p>No modules yet. Click "Add Module" to start building your course.</p>
          </div>
        )}
      </div>

      <div className="content-builder-actions">
        <button
          type="button"
          onClick={addModule}
          className="btn btn-primary"
        >
          Add Module
        </button>
      </div>
    </div>
  );
};

export default CourseContentBuilder;
